import { describe, it } from 'node:test';
import { api, startTestServer } from './helpers.ts';

describe('GET /shipments on a large dataset', () => {
  it('lists newest first, honours limit, stays fast with 5000 shipments, and never serves a stale eta', async () => {
    const srv = await startTestServer();
    try {
      const base = Date.UTC(2026, 0, 5, 8); // a Monday, before the 14:00 cutoff
      let firstId = '';
      for (let i = 0; i < 5000; i++) {
        const s = srv.store.addShipment(
          {
            trackingNumber: `T${i}`,
            carrier: 'DHL',
            serviceLevel: 'standard',
            recipient: { name: 'A', street: 'B', zip: '1010', city: 'Wien', country: 'AT' },
          },
          new Date(base + i * 60_000),
        );
        if (i === 4999) firstId = s.id; // newest
      }

      const t0 = performance.now();
      const res = await api(srv.url, 'GET', '/shipments?limit=50');
      const elapsed = performance.now() - t0;

      assert.equal(res.status, 200);
      assert.equal(res.body.count, 50);
      assert.equal(res.body.items[0].id, firstId);
      const dates = res.body.items.map((i: { created_at: string }) => i.created_at);
      assert.deepEqual(dates, [...dates].sort().reverse());
      assert.ok(elapsed < 250, `list took ${elapsed.toFixed(0)} ms`); // generous bound, guards against O(n) per-item work

      // An ETA is computed fresh per request: a new exception event must show up immediately.
      const before = res.body.items[0].eta;
      srv.store.addEvent(firstId, 'exception');
      const after = await api(srv.url, 'GET', '/shipments?limit=1');
      assert.notEqual(after.body.items[0].eta, before);
    } finally {
      await srv.close();
    }
  });
});
"}

